-- 실행 계획을 비교한다

@Test
void 계획() {
    for (int i = 0; i < 20000; i++) em.persist(new Member("p" + i, 10));
    em.createNativeQuery("create index idx_username on member(username)")
            .executeUpdate();
    em.flush(); em.clear();

    System.out.println(em.createNativeQuery(
            "explain analyze select * from member" +
            " where (null is null or username = null)")
        .getResultList().get(0));

    System.out.println(em.createNativeQuery(
            "explain analyze select * from member where username = 'p1'")
        .getResultList().get(0));
}

